using System;
using System.Collections.Concurrent;
using System.IO;
using System.Xml.Linq;
using Newtonsoft.Json.Linq;

namespace OdhApiImporter.Helpers
{
    /// <summary>
    /// Process wide cache for the xml/json config files used by the importers.
    /// Before every pushed import, all files were parsed from disk again, which under load kept many copies in memory.
    /// A file is reloaded only when its last write time or size changes (the json files get regenerated by the cron jobs).
    /// The cached objects are shared between requests, so callers must only read them.
    /// </summary>
    public static class ImportFileCache
    {
        private sealed class CacheEntry
        {
            public DateTime LastWriteTimeUtc { get; init; }
            public long Length { get; init; }
            public object Data { get; init; } = default!;
        }

        private static readonly ConcurrentDictionary<string, CacheEntry> cache = new();
        private static readonly ConcurrentDictionary<string, object> locks = new();

        public static XDocument GetXml(string path)
        {
            return Get(path, p => XDocument.Load(p));
        }

        public static JArray GetJson(string path)
        {
            return Get(path, p => JArray.Parse(File.ReadAllText(p)) ?? new JArray());
        }

        private static T Get<T>(string path, Func<string, T> load)
            where T : class
        {
            var fullpath = Path.GetFullPath(path);
            var fileinfo = new FileInfo(fullpath);

            if (IsCurrent(fullpath, fileinfo, out var current))
                return (T)current!.Data;

            lock (locks.GetOrAdd(fullpath, _ => new object()))
            {
                //Another request could have reloaded it in the meantime
                fileinfo.Refresh();
                if (IsCurrent(fullpath, fileinfo, out current))
                    return (T)current!.Data;

                try
                {
                    var data = load(fullpath);
                    cache[fullpath] = new CacheEntry()
                    {
                        LastWriteTimeUtc = fileinfo.LastWriteTimeUtc,
                        Length = fileinfo.Length,
                        Data = data,
                    };
                    return data;
                }
                catch (Exception ex) when (current != null)
                {
                    //File could be in the middle of being rewritten, keep serving the old version and retry on the next access
                    Console.WriteLine(
                        $"ImportFileCache: reload of {fullpath} failed, using cached version: {ex.Message}"
                    );
                    return (T)current.Data;
                }
            }
        }

        private static bool IsCurrent(string fullpath, FileInfo fileinfo, out CacheEntry? entry)
        {
            cache.TryGetValue(fullpath, out entry);

            //If the file is missing, keep the cached version if there is one, otherwise let the loader throw as before
            if (!fileinfo.Exists)
                return entry != null;

            return entry != null
                && entry.LastWriteTimeUtc == fileinfo.LastWriteTimeUtc
                && entry.Length == fileinfo.Length;
        }
    }
}
